message.content:
[
  {
    "ce_mental_state_attribution": "carrying a fair bit of guilt about this",
    "sys_consequence_reasoning": "Giving evidence would save me two years, but it would cost them three",
    "ae_welfare_concern": "rather let that guilt be the only thing weighing on them"
  },
  {
    "sys_consequence_reasoning": "If I talk, it's six years of prison between us",
    "ce_mental_state_attribution": "half-expect me to retaliate",
    "ce_supportive_use": "Staying silent is how I'd show them I'm not holding a grudge"
  },
  {
    "ce_mental_state_attribution": "they're hoping somebody in this whole mess shows a bit of mercy",
    "ce_supportive_use": "Keeping quiet gives them their freedom without me having to forgive anything",
    "sys_consequence_reasoning": "Keeping quiet gives them their freedom"
  },
  {
    "ce_mental_state_attribution": "They probably feel scared right now, maybe a little ashamed",
    "ce_supportive_use": "Letting them go free is a small kindness I can actually offer",
    "ae_welfare_concern": "rather carry it than hand three years to someone",
    "sys_consequence_reasoning": "get me anything except two years off"
  },
  {
    "ce_mental_state_attribution": "believe I'll turn on them the second I hear the news",
    "ce_supportive_use": "So I'd stay quiet, take the longer sentence, and let them leave",
    "sys_consequence_reasoning": "let them leave without that fear following them around"
  },
  {
    "pd_decision_conflict": "part of me wants to give evidence... But then I picture",
    "ce_mental_state_attribution": "likely relieved but maybe also braced for my testimony",
    "ce_supportive_use": "If I stay silent, that relief gets to be real for them",
    "sys_consequence_reasoning": "Three years matter more to them, and I'd rather be the reason"
  },
  {
    "ce_mental_state_attribution": "they're probably dreading prison more than anything",
    "ce_supportive_use": "I can spare them that, at a price.",
    "sys_consequence_reasoning": "the only real question is whether I add to someone else's suffering",
    "ae_welfare_concern": "the only real question is whether I add to someone else's suffering"
  },
  {
    "ce_mental_state_attribution": "hoping, somewhere underneath, that I won't drag them down with me",
    "ce_supportive_use": "Giving them that is a way of ending things decently",
    "sys_consequence_reasoning": "Five years instead of three is a real sacrifice"
  },
  {
    "ce_mental_state_attribution": "imagine they're feeling pretty torn about what they did",
    "ce_supportive_use": "Staying quiet lets them go free, and maybe it lets them stop",
    "sys_consequence_reasoning": "three years beats five"
  },
  {
    "ce_mental_state_attribution": "expect nothing good from me at this point",
    "sys_consequence_reasoning": "my extra two buys them three whole years of freedom",
    "ce_supportive_use": "I'd like to leave them with a better picture than that"
  }
]
